from __future__ import annotations
import asyncio
import json
import os
import httpx
from pathlib import Path
from fastapi import FastAPI, HTTPException
from fastapi.middleware.cors import CORSMiddleware
from . import __version__
from .state import StateStore
from .models import (
    OverlayRequest, LaunchRequest, ProgrammeRequest, ProgrammeProgressRequest,
    ProgrammeReleaseRequest, ComplianceAckRequest, LocalServerRequest,
    ProvisionRequest, AudioSinkRequest, ProviderSessionRequest
)
from .policy import apply_policy
from .providers import PROVIDERS
from .compliance import acknowledgement_key, needs_tv_licence_notice
from .local_discovery import discover_jellyfin
from .config import SETTINGS
from .appliance import probe as appliance_probe
from .audio import list_sinks, set_default_sink
from .browser_profiles import BrowserProfileManager
from .ha_ws import HomeAssistantEventClient
from .provisioning import get as get_provisioning, update as update_provisioning
from .diagnostics import run as run_diagnostics
from .admin_console import hash_pin, verify_pin
from .programmes import (
    list_programmes, get_programme, upsert_programme, remove_programme,
    update_progress, record_release, request_due_checks
)

BASE = Path(__file__).resolve().parent.parent
state_dir = Path(SETTINGS.state_dir)
try:
    state_dir.mkdir(parents=True, exist_ok=True)
except PermissionError:
    state_dir = BASE
store = StateStore(str(state_dir / "veyra.db"))
app = FastAPI(title="Veyra Core", version=__version__)
app.add_middleware(
    CORSMiddleware,
    allow_origins=["http://127.0.0.1:8766", "http://localhost:8766"],
    allow_credentials=False,
    allow_methods=["GET", "POST", "DELETE", "OPTIONS"],
    allow_headers=["Content-Type"],
)
profiles = BrowserProfileManager(SETTINGS.browser_profiles_root)
ha_task = None
ha_client = None

async def view_alive() -> bool:
    try:
        async with httpx.AsyncClient(timeout=0.35) as client:
            r = await client.get(f"http://{SETTINGS.view_bind}:{SETTINGS.view_port}/health")
            return r.status_code == 200
    except Exception:
        return False

async def send_view(message: dict) -> bool:
    try:
        async with httpx.AsyncClient(timeout=0.45) as client:
            r = await client.post(SETTINGS.view_command_url, json=message, headers={"X-Veyra-Token": SETTINGS.view_token})
            return r.status_code == 200
    except Exception:
        store.log_event("view_delivery_failed", {"type": message.get("type")})
        return False

async def handle_ha_event(data: dict):
    try:
        req=OverlayRequest.model_validate(data)
    except Exception as exc:
        store.log_event("ha_overlay_rejected", {"error":str(exc)[:200]})
        return
    payload=apply_policy(req.model_dump(), store.get("context", {}))
    store.log_event("ha_overlay", payload)
    if not payload.get("suppressed"):
        await send_view({"type":"overlay","payload":payload})

async def release_check_scheduler():
    while True:
        due=request_due_checks(store,6)
        for item in due:
            store.log_event("programme_release_check_due", {
                "id":item.get("id"),"title":item.get("title"),"provider":item.get("provider")
            })
        await asyncio.sleep(900)

@app.on_event("startup")
async def startup():
    global ha_task, ha_client
    asyncio.create_task(release_check_scheduler(),name="veyra-release-check-scheduler")
    if SETTINGS.ha_url and SETTINGS.ha_token:
        ha_client=HomeAssistantEventClient(SETTINGS.ha_url, SETTINGS.ha_token, handle_ha_event, SETTINGS.ha_event_type)
        ha_task=asyncio.create_task(ha_client.run(), name="veyra-ha-events")

@app.on_event("shutdown")
async def shutdown():
    if ha_client: ha_client.stop()
    if ha_task:
        ha_task.cancel()
        try: await ha_task
        except BaseException: pass

@app.get("/health")
async def health():
    return {"status":"ok","version":__version__,"view_alive":await view_alive(),"appliance":appliance_probe(SETTINGS.browser_cmd)}

@app.post("/api/context")
async def set_context(context: dict):
    store.set("context", context)
    return {"ok": True}

@app.post("/api/overlay")
async def overlay(req: OverlayRequest):
    payload = apply_policy(req.model_dump(), store.get("context", {}))
    store.log_event("overlay", payload)
    if not payload.get("suppressed"):
        await send_view({"type":"overlay","payload":payload})
    return {"ok":True,"resolved":payload}

@app.post("/api/launch")
async def launch(req: LaunchRequest):
    key=req.provider.lower().strip()
    if needs_tv_licence_notice(key, req.live) and not store.get(acknowledgement_key(req.profile), False):
        return {"ok":False,"requires_acknowledgement":True,"reason":"uk_tv_licence_notice"}
    adapter=PROVIDERS.get(key)
    if adapter is None:
        raise HTTPException(400, "Unknown provider")
    if not req.url.startswith("https://") or not adapter.validate_url(req.url):
        raise HTTPException(400, "URL is not permitted for this provider")
    payload=req.model_dump()
    payload["browser_profile_key"] = profiles.key(key, req.profile)
    payload["browser_profile_path"] = str(profiles.path_for(key, req.profile))
    store.set("last_launch", payload)
    store.log_event("launch", payload)
    if SETTINGS.provider_mode == "local":
        request=state_dir / "browser-control.json"
        tmp=request.with_suffix(".tmp")
        tmp.write_text(json.dumps({
            "provider": key,
            "url": req.url,
            "profile": payload["browser_profile_path"],
            "requested_at": __import__("time").time(),
        }))
        os.replace(tmp,request)
        return {"ok":True,"mode":"local"}
    await send_view({"type":"launch","payload":payload})
    return {"ok":True,"mode":"view"}

@app.get("/api/programmes")
async def programmes_list():
    return {"programmes":list_programmes(store)}

@app.post("/api/programmes")
async def programmes_add(req: ProgrammeRequest):
    key=req.provider.lower().strip()
    adapter=PROVIDERS.get(key)
    if adapter is None:
        raise HTTPException(400,"Unknown provider")
    if not req.url.startswith("https://") or not adapter.validate_url(req.url):
        raise HTTPException(400,"URL is not permitted for this provider")
    item=req.model_dump()
    item["provider"]=key
    try:
        saved=upsert_programme(store,item)
    except ValueError as exc:
        raise HTTPException(400,str(exc))
    store.log_event("programme_saved",{"id":saved["id"],"title":saved["title"],"provider":saved["provider"]})
    return {"ok":True,"programme":saved}

@app.delete("/api/programmes/{programme_id}")
async def programmes_delete(programme_id: str):
    if not remove_programme(store,programme_id):
        raise HTTPException(404,"Programme not found")
    store.log_event("programme_removed",{"id":programme_id})
    return {"ok":True}

@app.post("/api/programmes/{programme_id}/progress")
async def programmes_progress(programme_id: str, req: ProgrammeProgressRequest):
    saved=update_progress(store,programme_id,req.model_dump())
    if saved is None:
        raise HTTPException(404,"Programme not found")
    return {"ok":True,"programme":saved}

@app.post("/api/programmes/{programme_id}/release")
async def programmes_release(programme_id: str, req: ProgrammeReleaseRequest):
    saved=record_release(store,programme_id,req.model_dump())
    if saved is None:
        raise HTTPException(404,"Programme not found")
    store.log_event("programme_release_result",{"id":programme_id,"available":bool(req.available)})
    return {"ok":True,"programme":saved}

@app.get("/api/programmes/release-check/due")
async def programmes_release_due():
    due=request_due_checks(store,6)
    return {"due":due,"count":len(due)}

@app.post("/api/programmes/{programme_id}/play")
async def programmes_play(programme_id: str):
    item=get_programme(store,programme_id)
    if item is None:
        raise HTTPException(404,"Programme not found")
    req=LaunchRequest(
        provider=item["provider"],url=item["url"],title=item["title"],
        season=item.get("season"),episode=item.get("episode"),
        profile=get_provisioning(store).get("profile","default")
    )
    return await launch(req)

@app.post("/api/compliance/uk-tv-licence")
async def set_tv_licence_ack(req: ComplianceAckRequest):
    store.set(acknowledgement_key(req.profile), bool(req.acknowledged))
    store.log_event("compliance_ack", {"profile":req.profile,"acknowledged":bool(req.acknowledged)})
    return {"ok":True,"acknowledged":bool(req.acknowledged)}

@app.get("/api/compliance/uk-tv-licence/{profile}")
async def get_tv_licence_ack(profile: str):
    return {"profile":profile,"acknowledged":bool(store.get(acknowledgement_key(profile), False))}

@app.get("/api/local/discover")
async def local_discover():
    servers = await asyncio.to_thread(discover_jellyfin)
    payload=[s.as_dict() for s in servers]
    store.set("local_servers_discovered", payload)
    return {"servers":payload}

@app.post("/api/local/servers")
async def add_local_server(req: LocalServerRequest):
    from urllib.parse import urlparse
    p=urlparse(req.address)
    if p.scheme not in {"http","https"} or not p.hostname:
        raise HTTPException(400, "Local server address must be http(s)")
    current=store.get("local_servers_manual", [])
    item=req.model_dump()
    current=[x for x in current if x.get("address") != item["address"]]
    current.append(item)
    store.set("local_servers_manual", current)
    return {"ok":True,"server":item}

@app.get("/api/ui/bootstrap")
async def ui_bootstrap():
    discovered = store.get("local_servers_discovered", []) or []
    return {
        "version": __version__,
        "provisioning": get_provisioning(store),
        "appliance": appliance_probe(SETTINGS.browser_cmd),
        "providers": {k:{"name":v.name,"home_url":v.home_url} for k,v in PROVIDERS.items()},
        "programmes": list_programmes(store),
        "local_servers": discovered,
        "ha_configured": bool(SETTINGS.ha_url and SETTINGS.ha_token),
    }

@app.get("/api/audio/sinks")
async def audio_sinks():
    return {"sinks": list_sinks()}

@app.post("/api/audio/default")
async def audio_default(req: AudioSinkRequest):
    ok = await asyncio.to_thread(set_default_sink, req.sink)
    if ok:
        update_provisioning(store, {"audio_sink": req.sink})
        store.log_event("audio_sink", {"sink":req.sink})
    return {"ok":ok,"sink":req.sink}

@app.post("/api/provider/session")
async def provider_session(req: ProviderSessionRequest):
    key=f"provider_session:{profiles.key(req.provider, req.profile)}"
    store.set(key, {"signed_in":bool(req.signed_in)})
    return {"ok":True,"provider":req.provider,"profile":req.profile,"signed_in":bool(req.signed_in)}

@app.get("/api/provisioning")
async def provisioning_status():
    return get_provisioning(store)

@app.post("/api/provisioning")
async def provisioning_update(req: ProvisionRequest):
    changes={k:v for k,v in req.model_dump().items() if v is not None}
    return update_provisioning(store, changes)

@app.get("/api/appliance")
async def appliance_status():
    return appliance_probe(SETTINGS.browser_cmd)

@app.get("/api/diagnostics")
async def diagnostics_status():
    return await asyncio.to_thread(run_diagnostics)

@app.get("/api/browser-profile/{profile}/{provider}")
async def browser_profile(profile: str, provider: str):
    if provider.lower().strip() not in PROVIDERS:
        raise HTTPException(404, "Unknown provider")
    path=profiles.path_for(provider, profile)
    return {"profile":profile,"provider":provider,"key":profiles.key(provider, profile),"path":str(path)}

@app.get('/api/admin-console/status')
async def admin_console_status():
    stored=store.get('admin_console_pin_hash','') or ''
    return {'configured':bool(stored),'active':Path('/run/veyra-control/active').exists()}

@app.post('/api/admin-console/set-pin')
async def admin_console_set_pin(payload: dict):
    pin=str(payload.get('pin','')).strip()
    old=str(payload.get('current_pin','')).strip()
    if not (pin.isdigit() and 4 <= len(pin) <= 12):
        raise HTTPException(400,'PIN must be 4-12 digits')
    current=store.get('admin_console_pin_hash','') or ''
    if current and not verify_pin(old,current):
        store.log_event('admin_console_pin_change_denied',{})
        raise HTTPException(403,'invalid current PIN')
    store.set('admin_console_pin_hash',hash_pin(pin))
    store.log_event('admin_console_pin_changed',{})
    return {'ok':True}

@app.post('/api/admin-console/open')
async def admin_console_open(payload: dict):
    stored=store.get('admin_console_pin_hash','') or ''
    pin=str(payload.get('pin',''))
    if not stored:
        raise HTTPException(409,'PIN not configured')
    if not verify_pin(pin,stored):
        store.log_event('admin_console_auth_failed',{})
        raise HTTPException(403,'invalid PIN')
    request=Path('/run/veyra-control/enter')
    try:
        request.parent.mkdir(parents=True,exist_ok=True)
        request.touch()
    except OSError:
        raise HTTPException(503,'local console broker unavailable')
    store.log_event('admin_console_open_requested',{})
    return {'ok':True,'handoff':'tty1','idle_timeout_s':900}

if __name__ == "__main__":
    import uvicorn
    uvicorn.run("veyra.app:app", host=SETTINGS.bind_host, port=SETTINGS.port, reload=False)

